export const LAB_CUSTOMER_TRAINING_COPY = Object.freeze({ en, es, pt, pl, ru, de, fr, it, ja, ko, ar }) as Readonly<Record<string, LabCustomerTrainingCopy>>
export const LAB_CUSTOMER_TRAINING_ERROR_CODES = ERR_CODES

export function labCustomerTrainingCopy(language: string | null | undefined): LabCustomerTrainingCopy {
  const key = String(language ?? 'en').toLowerCase().split(/[-_]/)[0]
  return LAB_CUSTOMER_TRAINING_COPY[key] ?? en
}
